(r/'site.css').write_text('''*{box-sizing:border-box}html{scroll-behavior:smooth}body{--bg:#f5f5f0;--ink:#172823;--muted:#647069;--card:#fff;--line:#dce1d9;margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui}body.dark{--bg:#101b18;--ink:#eef4ef;--muted:#a7b6ad;--card:#192a23;--line:#34483d}a{color:inherit;text-decoration:none}button,select{font:inherit;color:inherit;background:var(--card);border:1px solid var(--line);border-radius:8px;padding:8px;cursor:pointer}header,footer{max-width:1200px;margin:auto;padding:24px;display:flex;align-items:center;gap:20px}header{border-bottom:1px solid var(--line)}.brand{font-size:23px;font-weight:800;display:flex;align-items:center;gap:8px}.brand img{width:30px}.brand span{color:#4a9b67}nav{margin-left:auto;display:flex;gap:24px}main{max-width:1200px;margin:auto;padding:0 24px}section{padding:64px 0}.hero{display:grid;grid-template-columns:1.1fr 1fr;gap:60px;align-items:center;padding:85px 0}small{font-size:12px;letter-spacing:.09em;color:var(--muted)}h1{font-size:clamp(42px,5.6vw,76px);line-height:1.07;letter-spacing:-.055em;margin:24px 0}h2{font-size:34px;letter-spacing:-.035em;line-height:1.2}p{color:var(--muted)}.actions{display:flex;gap:10px;flex-wrap:wrap;margin:30px 0 18px}.button{display:inline-block;padding:13px 19px;border:1px solid var(--line);border-radius:10px;background:var(--card);font-weight:650}.primary{background:#286a48;color:#fff;border-color:#286a48}.preview{background:#e4ebe0;border:1px solid #c8d6c6;border-radius:18px;box-shadow:0 24px 70px #1e41281c;transform:rotate(2deg);color:#172823}.window{border-bottom:1px solid #c8d6c6;padding:14px;color:#859984;font-size:12px}.window span{float:right}.document{padding:28px}.document h2{font-size:38px}mark{background:#c4e3a3;padding:3px}.translation{background:white;border:1px solid #a4c38e;border-radius:12px;padding:18px;margin-top:20px;box-shadow:0 10px 25px #27432d15}.translation p{color:#172823}.translation kbd{float:right}.workflow{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;border-block:1px solid var(--line);padding:28px 0}.workflow b{color:#5c976b;font-size:12px}.workflow h3{font-size:16px;margin:8px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.cards article{background:var(--card);border:1px solid var(--line);padding:28px;border-radius:16px}.cards article span{font-size:28px;color:#4a9b67}.support{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line)}footer{border-top:1px solid var(--line);font-size:13px;flex-wrap:wrap;color:var(--muted)}footer span{margin-right:auto}.note:empty{display:none}.note{max-width:800px}.note p{white-space:pre-line}@media(max-width:800px){.hero{grid-template-columns:1fr;gap:30px;padding:45px 0}.preview{transform:none}.cards{grid-template-columns:1fr}nav{display:none}header{gap:10px}#language{margin-left:auto}.support{gap:20px;flex-wrap:wrap}.workflow{gap:10px}.workflow h3{font-size:13px}section{padding:40px 0}h1{font-size:48px}}''',encoding='utf-8')
(r/'site.js').write_text('''const data='''+json.dumps(rows,ensure_ascii=False)+''';
const picker=document.getElementById('language');const initial=localStorage.getItem('cx-language') || navigator.language.split('-')[0];picker.value=data[initial]?initial:'en';
function apply(){const lang=picker.value;document.documentElement.lang=lang;localStorage.setItem('cx-language',lang);document.querySelectorAll('[data-t]').forEach(el=>el.textContent=data[lang][Number(el.dataset.t)]);const page=location.pathname.split('/').pop();const ids={ 'help.html':[20,21],'privacy.html':[5,22],'safe.html':[5,22],'about.html':[6,23],'updates.html':[24,2] };const box=document.getElementById('pageContent');box.replaceChildren();if(ids[page]){const [a,b]=ids[page];const h=document.createElement('h2');h.textContent=data[lang][a];const p=document.createElement('p');p.textContent=data[lang][b];box.append(h,p);} }
picker.onchange=apply;apply();document.querySelectorAll('.edge').forEach(a=>{a.href='https://microsoftedge.microsoft.com/addons/detail/çevirmenx/mjmjodgddimmcpgofieaimjapjjnonnp';a.onclick=()=>{if(!/Edg\//.test(navigator.userAgent))alert(data[picker.value][26]);};});document.querySelector('.chrome').onclick=()=>setTimeout(()=>location.assign('help.html'),800);
const theme=localStorage.getItem('cx-theme') || (matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light');document.body.classList.toggle('dark',theme==='dark');document.getElementById('theme').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('cx-theme',document.body.classList.contains('dark')?'dark':'light');};
''',encoding='utf-8')
